from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past")
        if end <= start:
            raise ValueError("End must be after start")

        # A patient can have at most one upcoming appointment.
        for appt in self._appointments.values():
            if appt["patient"] == patient and not appt["cancelled_upcoming_block"]:
                if appt["start"] >= now or (
                    appt["start"] <= now < appt["end"]
                ):
                    raise ValueError(
                        "Patient already has an upcoming appointment"
                    )

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not free at that time")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "active": True,
            "cancelled_upcoming_block": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None or not appt["active"]:
            raise ValueError("No such active appointment")
        appt["active"] = False
        # If cancelled less than 24 hours before start, the slot remains blocked.
        if appt["start"] - now < timedelta(hours=24):
            appt["cancelled_upcoming_block"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not appt["active"] and not appt["cancelled_upcoming_block"]:
                continue
            # Overlap check: touch => not overlap
            if start < appt["end"] and appt["start"] < end:
                return False
        return True
